// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2008, "8-9", [{"author":"И. Иткин","question":"Как правильно закончить фразу: <em>Вася — парень свой ...</em> ?","choices":["<em>в доску</em>","<em>в стельку</em>","<em>в лепёшку</em>","<em>в точку</em>","<em>на бочку</em>."],"key":"А","review":["Разговорная фраза о Васе","Подбери устойчивое усиление для слова «свой». Остальные обороты обычно сочетаются с другими словами.","Говорят «свой в доску» о человеке, которого считают полностью своим, близким по духу."]},{"author":"Л. Фёдорова","question":"Какое слово не употребляется в формах множественного числа?","choices":["<em>небо</em>","<em>человек</em>","<em>вино</em>","<em>трава</em>","<em>молоко</em>."],"key":"Д","review":["Множественное число","Проверь особые формы вроде «небеса» и «люди». Другим словам множественное число может понадобиться для названий разных сортов.","Есть «небеса», «люди», «вина» и «травы». В обычном литературном употреблении вещественное «молоко» множественного числа не имеет."]},{"author":"О. Шеманаева","question":"Как называется заграждение, служащее защитой во время уличных боёв?","choices":["<em>блокада</em>","<em>канонада</em>","<em>коррида</em>","<em>баррикада</em>","<em>барракуда</em>."],"key":"Г","review":["Заграждение на улице","Представь сооружение из подручных предметов, которое перекрывает улицу и служит укрытием.","Такое заграждение называется баррикадой. «Канонада» обозначает стрельбу, а «блокада» — окружение или изоляцию."]},{"author":"И. Иткин","question":"Как правильно?","choices":["<em>Он достиг высокого положения посредством подкупа и обмана.</em>","<em>Он достиг высокого положения по средствам подкупа и обмана.</em>","<em>Он достиг высокого положения посредствам подкупа и обмана.</em>","<em>Он достиг высокого положения по средствием подкупа и обмана.</em>","<em>Он достиг высокого положения посредствием подкупа и обмана.</em>"],"key":"А","review":["Слово со значением средства","Выражение можно заменить словами «при помощи». Проверь написание одного слова, а не сочетания с «по».","Правильно «посредством подкупа и обмана». «Посредством» пишется слитно и требует родительного падежа."]},{"author":"Б. Иомдин","question":"У какого из этих глаголов нет парного ему глагола несовершенного вида с приставкой <em>у-</em>?","choices":["<em>убежать</em>","<em>угадать</em>","<em>уронить</em>","<em>угнать</em>","<em>узнать</em>."],"key":"В","review":["Видовые пары с «у-»","Подбери видовые пары для «убежать», «угадать», «угнать» и «узнать». Затем проверь, нужна ли «у-» в паре к «уронить».","Получаются «убегать», «угадывать», «угонять», «узнавать». К «уронить» соответствует «ронять», без «у-»."]},{"author":"Б. Иомдин","question":"Какая поговорка издавна существует в русском языке?","choices":["<em>Слово не воробей, поймают — вылетишь.</em>","<em>Слово не воробей, поймают — не вылетишь.</em>","<em>Слово не воробей, вылетишь — не поймают.</em>","<em>Слово не воробей, вылетит — не поймаешь.</em>","<em>Слово не воробей, не поймаешь — вылетит.</em>"],"key":"Г","review":["Слово и воробей","Восстанови смысл поговорки: сказанного уже не вернуть. Сопоставь его с образом улетевшей птицы.","Говорят «Слово не воробей, вылетит — не поймаешь». Другие реплики меняют смысл или порядок частей."]},{"author":"Б. Иомдин","question":"Что такое <em>лесосплав</em>?","choices":["‘сплав дерева с другими веществами’","‘транспортировка брёвен вниз по реке’","‘свалка для отходов производства, расположенная в лесу’","‘плавание на плотах по рекам и озёрам’","‘грузовой порт на лесном берегу’."],"key":"Б","review":["Смысл слова «лесосплав»","Раздели слово на части и вспомни, что можно пустить течением вниз по реке.","Лесосплав — перевозка брёвен по воде. Используется течение реки, а «лес» называет перевозимую древесину."]},{"author":"Б. Иомдин","question":"Даны словосочетания: 1) <em>в краю далёком,</em> 2) <em>в Красноярском краю,</em> 3) <em>хата с краю,</em> 4) <em>на краю гибели.</em> Какое из них содержит ошибку?","choices":["1","2","3","4","никакое."],"key":"Б","review":["Форма слова «край»","Сравни название административной территории с поэтическим «в краю» и выражениями о крае чего-либо.","Официально говорят «в Красноярском крае». «В краю далёком», «хата с краю» и «на краю гибели» допустимы."]},{"author":"П. Аркадьев","question":"Какое слово существует?","choices":["<em>тогоже</em>","<em>тогдаже</em>","<em>тойже</em>","<em>туже</em>","<em>тудаже</em>."],"key":"Г","review":["Частица или одно слово","Проверь, где «же» — отдельная частица, а где последние буквы входят в простую форму другого слова.","«Туже» — сравнительная степень от «тугой» или «туго». Остальные сочетания пишутся раздельно с «же»."]},{"author":"Б. Иомдин","question":"Какое из этих слов не может быть причастием?","choices":["<em>сжатый</em>","<em>зажатый</em>","<em>прижатый</em>","<em>вожатый</em>","<em>нажатый</em>."],"key":"Г","review":["Причастия и название человека","Подбери глагол для каждой формы. Причастие означает признак по действию, например «который сжали».","«Сжатый», «зажатый», «прижатый» и «нажатый» — причастия. «Вожатый» называет человека."]},{"author":"И. Рубанов","question":"<em>Юбиляр был награждён орденом ...</em> . Как правильно закончить эту фразу?","choices":["<em>«За заслуги перед Отечеством второй степени».</em>","<em>за заслуги перед Отечеством «второй степени».</em>","<em>«За заслуги» перед Отечеством второй степени.</em>","<em>«За заслуги перед Отечеством» второй степени.</em>","<em>за заслуги «перед Отечеством второй степени».</em>"],"key":"Г","review":["Кавычки в названии ордена","Отдели собственное название награды от сведений о её степени. Степень относится к ордену целиком.","Пишут «орденом „За заслуги перед Отечеством“ второй степени». Слова «второй степени» стоят после кавычек."]},{"author":"О. Шеманаева","question":"<em>Пора научиться сохранять душевное равновесие … от жизненных обстоятельств.</em>","choices":["<em>в не зависимости</em>","<em>вне зависимости</em>","<em>в независимости</em>","<em>внезависимости</em>","<em>вне за висимости</em>."],"key":"Б","review":["Оборот о независимости","Подбери выражение со значением «независимо от обстоятельств». Проверь границы слов.","Правильно «вне зависимости от». Предлог «вне» и существительное «зависимость» пишутся раздельно."]},{"author":"И. Рубанов","question":"Какое из этих выражений имеет примерно тот же смысл, что «<em>ни свет ни заря</em>»?","choices":["<em>ни рыба ни мясо</em>","<em>ни дна ни покрышки</em>","<em>с первыми петухами</em>","<em>хоть глаз выколи</em>","<em>до первой звезды</em>."],"key":"В","review":["Два оборота о времени","«Ни свет ни заря» означает очень рано. Ищи другой традиционный образ начала дня.","«С первыми петухами» значит на рассвете или очень рано. Выражение имеет тот же смысл."]},{"author":"И. Иткин","question":"Наречия на <em>-ую</em> образуются от прилагательных. Зная ударение прилагательного, в большинстве случаев можно с помощью простого правила определить, на какой слог будет падать ударение в наречии. Для какого из следующих наречий это правило не выполняется?","choices":["<em>вручную</em>","<em>врукопашную</em>","<em>втёмную</em>","<em>напрямую</em>","<em>вплотную</em>."],"key":"Д","review":["Ударение в наречиях","Восстанови прилагательные: «ручной», «рукопашный», «тёмный», «прямой», «плотный». Сравни место ударения в формах.","В «ручну́ю», «рукопа́шную», «тёмную», «пряму́ю» оно совпадает с местом ударения в наречиях. У «пло́тную» ударение на корне, а в «вплотну́ю» — на «у»."]},{"author":"Н. Валеева","question":"В каком из данных слов каждый слог совпадает по написанию с какой-нибудь частицей русского языка?","choices":["<em>непросто</em>","<em>зато</em>","<em>нежели</em>","<em>незачем</em>","<em>неужели</em>."],"key":"В","review":["Каждый слог — частица","Раздели слова на слоги и проверь, можно ли каждый употребить отдельно, например в вопросе или возражении.","«Не-же-ли» состоит из «не», «же», «ли». Все три сочетания букв существуют как частицы."]},{"author":"Н. Валеева","question":"<em>Прибыли возросли … качественной связи и безлимитного Интернета</em>. Как правильнее заполнить пропуск?","choices":["<em>благодаря</em>","<em>в связи с</em>","<em>вследствие</em>","<em>за счёт</em>","<em>путём</em>."],"key":"Г","review":["Как выросли прибыли","Проверь, какие предлоги допускают родительный падеж «связи и Интернета». Затем выбери оборот об источнике прироста.","«За счёт качественной связи и безлимитного Интернета» указывает, что обеспечило прибыль. После «благодаря» ожидался бы дательный «Интернету», после «в связи с» — творительный."]},{"author":"Л. Фёдорова","question":"Какое из названий видов транспорта русское по происхождению?","choices":["<em>метро</em>","<em>трамвай</em>","<em>автобус</em>","<em>такси</em>","<em>электричка</em>."],"key":"Д","review":["Как назвали транспорт","Определи, какое слово было образовано в русском языке от уже известного названия с уменьшительным суффиксом.","«Электричка» образовано в русском от «электрический поезд». Метро, трамвай, автобус и такси заимствованы как названия."]},{"author":"И. Иткин","question":"Как правильно заполнить пропуск во фразе: <em>Вася ... в физике, зато он замечательно решает задачи конкурса «Русский медвежонок»</em>?","choices":["<em>ни бум бум</em>","<em>ни бумбум</em>","<em>нибумбум</em>","<em>ни-бум-бум</em>","<em>ни бум-бум</em>."],"key":"Д","review":["Разговорный оборот","Выражение означает совсем не разбираться в предмете. Вспомни, как пишется повтор одинакового звукоподражания.","Правильно «ни бум-бум». «Ни» стоит отдельно, между двумя «бум» добавляется дефис."]},{"author":"Н. Валеева","question":"<em>Маша пригласила на день рождения пять подруг. Четыре уже пришли, а одна из … задержалась в школе.</em> Что надо поставить вместо многоточия?","choices":["<em>госте́й</em>","<em>го́стей</em>","<em>гостий</em>","<em>гостьев</em>","<em>гость</em>."],"key":"В","review":["Множественное число гостьи","В предложении речь именно о подругах, поэтому исходное слово «гостья». Поставь его после «одна из».","У «гостьи» родительный падеж множественного числа — «гостий». «Гостей» — обычная форма слова «гость»."]},{"author":"О. Шеманаева","question":"Перед вами — отрывок из романа А. Дюма «Чёрный тюльпан»:\n«— Я пробирался боковыми улочками.\n— Ты прятался, Ян?\n— Мне надо было попасть к тебе, не теряя времени. Я поступил так, как поступают в политике и на море при встречном ветре: я ...»\nЧто стоит в тексте на месте многоточия?","choices":["<em>дрейфовал</em>","<em>лавировал</em>","<em>шёл на абордаж</em>","<em>свистал всех наверх</em>","<em>поднял паруса</em>."],"key":"Б","review":["Слово у Дюма","При встречном ветре парусник идёт к цели, меняя направление. В политике тот же глагол означает действовать обходными путями.","«Лавировал» подходит и к движению парусника, и к маневрированию в политике. Это слово употреблено в цитате."]},{"author":"Н. Валеева","question":"Какое из перечисленных ниже слов появилось в русском языке только в XX веке?","choices":["<em>вратарь</em>","<em>нападающий</em>","<em>защитник</em>","<em>полузащитник</em>","<em>судья.</em>"],"key":"Г","review":["Слово из футбола","Проверь, какие слова существовали вне спорта. Среди вариантов есть название конкретной футбольной позиции.","«Полузащитник» появился с футбольной терминологией XX века. «Вратарь», «нападающий», «защитник» и «судья» раньше употреблялись вне футбола."]},{"author":"Н. Валеева","question":"Какая из данных ниже фраз может быть понята двумя способами?","choices":["<em>Нет терроризму!</em>","<em>Нет войне!</em>","<em>Нет насилию!</em>","<em>Нет агрессии!</em>","<em>Нет равнодушию!</em>"],"key":"Г","review":["Два смысла фразы с «нет»","Сравни «нет чего?» при отсутствии и «нет чему?» при призыве отказаться. Ищи совпадающее написание падежей.","«Нет агрессии» может означать отсутствие агрессии или призыв выступить против неё. У «агрессии» родительный и дательный имеют одинаковую форму."]},{"author":"О. Шеманаева","question":"От какого из этих слов в русском литературном языке нельзя образовать глагол?","choices":["<em>рука</em>","<em>губа</em>","<em>глаз</em>","<em>локоть</em>","<em>щека</em>."],"key":"Д","review":["Названия частей тела","Образуй глаголы от названий частей тела. Могут меняться некоторые согласные, например «к» на «ч».","Есть «вручить», «пригубить», «глазеть» и «облокотиться». От «щека» соответствующего общеупотребительного литературного глагола нет."]},{"author":"В. Черванёва","question":"Какое из этих слов исторически не родственно слову <em>яд</em>?","choices":["<em>противоядие</em>","<em>всеядный</em>","<em>яство</em>","<em>еда</em>","все эти слова исторически родственны."],"key":"Д","review":["Семейство слов о пище","Вспомни, что в древности могло означать «ядь». Сравни слова с названием еды и глаголом «есть».","Старое «ядь» означало пищу. «Яд», «противоядие», «всеядный», «яство» и «еда» исторически относятся к одному семейству."]},{"author":"О. Шеманаева","question":"Перед вами известное четверостишие из стихотворения Г. Гейне в переводе М. Ю. Лермонтова:\n<em>И снится ей всё, что в пустыне далёкой,\nВ том крае, где солнца восход,\nОдна и грустна на утёсе горючем\nПрекрасная пальма растёт.</em>\nКаким членом предложения является слово <em>всё</em>?","choices":["подлежащим","сказуемым","дополнением","обстоятельством","определением."],"key":"Г","review":["Роль слова в стихе","Прочитай «снится» с вопросом «что?». Затем проверь, можно ли заменить «всё» словами «постоянно» или «всё время».","Сосне всё время снится, что растёт пальма. Здесь «всё» означает постоянство и служит обстоятельством."]},{"author":"И. Иткин","question":"Даны суффиксы: <em>-еств(о), -ин(а), -ищ(е)</em>. Какие из них могут встречаться после суффикса превосходной степени прилагательных <em>-ейш-?</em>","choices":["только <em>-ин(а)</em>","только <em>-ищ(е)</em>","<em>-еств(о)</em> и <em>-ин(а)</em>","<em>-еств(о)</em> и <em>-ищ(е)</em>","никакие."],"key":"В","review":["Суффиксы после «-ейш-»","Подбери существительные от «святейший» и «старейший». Посмотри, что остаётся после «-ейш-».","В «святейшество» после «-ейш-» стоит «-еств-», в «старейшина» — «-ин-». Подходят два суффикса."]},{"author":"И. Иткин","question":"В интервью известный актёр сказал: «<em>Я незлобли́в и миротворец по природе</em>». А как надо было сказать?","choices":["именно так и надо было","<em>незло́блив</em>","<em>незлобчив</em>","<em>незлобив</em>","<em>беззлоблив</em>."],"key":"Г","review":["Краткое прилагательное","Восстанови полное прилагательное о человеке без злобы. Затем образуй краткую форму мужского рода.","Полная форма — «незлобивый», краткая — «незлобив». Лишняя «л» появилась в исходной реплике."]},{"author":"И. Иткин","question":"В фамилии венгерского поэта <em>Михая Вёрёшмарти</em> — две буквы <em>ё</em>, а между ними — ещё одна буква. Какое минимальное количество букв между двумя буквами <em>ё</em> может быть в русском по происхождению слове, пишущемся слитно?","choices":["0","1","2","4","русских по происхождению слов, в которых пишется больше одной буквы <em>ё</em>, нет и быть не может."],"key":"В","review":["Расстояние между буквами «ё»","Ищи сложное слово, где в каждой части есть «ё». Сравни начало «трёх-» со словом о щётках.","В «трёхщёточный» между «ё» стоят «х» и «щ». Две основы с ударным «ё» разделяет конец первой и начало второй: либо две согласные, либо согласная и «ъ» перед начальной «ё»."]},{"author":"А. Бердичевский","question":"Дан отрывок из пьесы Уильяма Шекспира «Гамлет, принц Датский» (перевод Бориса Пастернака), в котором Гамлет критически отзывается о произошедшей недавно в Датском королевстве смене правителей. Одно слово пропущено.\nГамлет.\n<em>Ты знаешь, дорогой Дамон,\nЮпитера орёл\nСлетел с престола, и на трон\nВоссел простой ... .</em>\nГорацио.\n<em>Вы могли бы и в рифму.</em>\nПропущенное слово Гамлет произносит с заметной паузой посередине. Что это за слово?","choices":["<em>орёл</em>","<em>осёл</em>","<em>осётр</em>","<em>павлин</em>","<em>баран</em>."],"key":"В","review":["Слово после паузы","По рифме после «орёл» ожидается одно животное. Пауза позволяет Гамлету начать ожидаемым слогом, но закончить другим словом.","Он говорит «ос…ётр». Горацио слышит, что ожидаемая рифма «орёл — осёл» намеренно не состоялась."]},{"author":"Л. Фёдорова","question":"Даны слова и выражения на новогреческом языке:\nο Γάλλος — француз;\nο Άγγλος μουσικός — английский музыкант;\nο Ρώσος γιατρός — русский врач;\nο ρωσικός χορός — русский танец;\nη Γαλλίδα μπαλαρίνα — французская балерина;\nο Γάλλος μάγειρας — французский повар;\nη αγγλική κουζίνα — английская кухня.\nКак будет по-новогречески: французская кухня, русская балерина, англичанка?","choices":["η Γαλλίδα κουζίνα, ο ρωσικός μπαλαρίνα, η αγγλική","η γαλλίδα κουζίνα, ο Ρώσος μπαλαρίνα, η Αγγλική","η γαλλίκα κουζίνα, η Ρωσικήδα μπαλαρίνα, η Αγγλικήδα","η γαλλική κουζίνα, η Ρωσίδι μπαλαρίνα, η Αγγλίδι","η γαλλική κουζίνα, η Ρωσίδα μπαλαρίνα, η Αγγλίδα."],"key":"Д","review":["Названия по-новогречески","Различи прилагательное к названию кухни и существительное о человеке. У женского рода в примерах артикль «η».","«Французская кухня» — «η γαλλική κουζίνα». По модели «Γαλλίδα» получаются «η Ρωσίδα μπαλαρίνα» и «η Αγγλίδα»."]}], {"year":2008,"grade":"8-9","tasksFile":"8-9.pdf","answersFile":"8-9-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2008.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
